const items = $input.all();

return items.map(item => {
  const data = item.json;
  const errors = [];

  const requiredFields = [
    "Sales Executive Name",
    "Sales Executive Email",
    "Customer Name",
    "Customer Email",
    "Product Code"
  ];

  for (const field of requiredFields) {
    if (!String(data[field] ?? "").trim()) {
      errors.push(`${field} is required`);
    }
  }

  const emailPattern = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

  for (const field of ["Sales Executive Email", "Customer Email"]) {
    if (data[field] && !emailPattern.test(String(data[field]).trim())) {
      errors.push(`Invalid ${field}`);
    }
  }

  const quantity = Number(data["Quantity"]);
  const discount = Number(data["Proposed Discount (%)"]);

  if (
    data["Quantity"] === "" ||
    data["Quantity"] == null ||
    !Number.isInteger(quantity) ||
    quantity <= 0
  ) {
    errors.push("Quantity must be a positive whole number");
  }

  if (
    data["Proposed Discount (%)"] === "" ||
    data["Proposed Discount (%)"] == null ||
    !Number.isFinite(discount) ||
    discount < 0 ||
    discount > 100
  ) {
    errors.push("Discount must be between 0 and 100");
  }

  return {
    json: {
      ...data,
      quantity: quantity,
      proposedDiscount: discount,
      validationStatus: errors.length === 0 ? "Valid" : "Invalid",
      validationErrors: errors,
      isValid: errors.length === 0
    }
  };
});

const requests = $('If Request Valid').all(0);
const products = $input.all();

return products.map((item, index) => {
  const product = item.json;
  const request = requests[index]?.json;

  if (!request) {
    throw new Error("Quotation request data not found");
  }

  const quantity = Number(request.quantity);
  const discountPercent = Number(request.proposedDiscount);
  const unitPrice = Number(product["Unit Price"]);
  const unitCost = Number(product["Unit Cost"]);

  if (
    !Number.isFinite(unitPrice) ||
    !Number.isFinite(unitCost) ||
    unitPrice <= 0 ||
    unitCost < 0
  ) {
    throw new Error("Invalid product pricing");
  }

  const subtotal = unitPrice * quantity;
  const discountAmount = subtotal * discountPercent / 100;
  const netAmount = subtotal - discountAmount;
  const totalCost = unitCost * quantity;
  const grossProfit = netAmount - totalCost;
  const grossMargin = netAmount > 0
    ? (grossProfit / netAmount) * 100
    : 0;

  return {
    json: {
      ...request,
      productName: product["Product Name"],
      productCode: product["Product Code"],
      unitPrice,
      unitCost,
      subtotal,
      discountAmount,
      netAmount,
      totalCost,
      grossProfit,
      grossMargin: Number(grossMargin.toFixed(2)),
      pricingStatus: "Calculated"
    }
  };
});

return $input.all().map(item => {
  const data = item.json;

  const discount = Number(data.proposedDiscount);
  const margin = Number(data.grossMargin);
  const maxDiscount = Number(data.maxAutoDiscount);
  const minMargin = Number(data.minProfitMargin);

  const discountWithinLimit = discount <= maxDiscount;
  const marginWithinLimit = margin >= minMargin;

  const autoApprovalEligible =
    discountWithinLimit && marginWithinLimit;

  const reasons = [];

  if (!discountWithinLimit) {
    reasons.push("Discount exceeds auto-approval limit");
  }

  if (!marginWithinLimit) {
    reasons.push("Gross margin below minimum threshold");
  }

  return {
    json: {
      ...data,
      discountWithinLimit,
      marginWithinLimit,
      autoApprovalEligible,
      approvalRequired: !autoApprovalEligible,
      approvalReasons: reasons,
      pricingPolicyStatus: autoApprovalEligible
        ? "Within Policy"
        : "Manager Review Required"
    }
  };
});
